import React from "react";
import {
  FaUser,
  FaPhone,
  FaMapMarkerAlt,
  FaImage,
  FaTag,
  FaQuestionCircle,
  FaClock,
  FaLink,
  FaChevronDown,
} from "react-icons/fa";

class CustomerRequestForm extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      fullName: "",
      mobile: "",
      landline: "",
      province: "",
      address: "",
      deviceType: "",
      deviceBrand: "",
      deviceIssue: "",
      visitTime: "",
      description: "",
    };

    this.handleChange = this.handleChange.bind(this);
    this.handleSubmit = this.handleSubmit.bind(this);
  }

  handleChange(field) {
    return (e) => {
      this.setState({
        [field]: e.target.value,
      });
    };
  }

  handleSubmit(e) {
    e.preventDefault();

    console.log(this.state);
  }

  render() {
    const {
      fullName,
      mobile,
      landline,
      province,
      address,
      deviceType,
      deviceBrand,
      deviceIssue,
      visitTime,
      description,
    } = this.state;

    return (
      <div
        dir="rtl"
        lang="fa"
        className="min-vh-100 bg-light py-3 px-2"
      >
        <div className="container-fluid">

          {/* کارت اصلی */}
          <div
            className="card border-0 shadow-sm mx-auto overflow-hidden"
            style={{
              maxWidth: "480px",
              borderRadius: "24px",
            }}
          >

            {/* Header */}
            <div
              className="text-white p-4"
              style={{
                background:
                  "linear-gradient(135deg, #0d6efd 0%, #4f46e5 100%)",
              }}
            >
              <div className="d-flex align-items-center gap-3">

                <div
                  className="d-flex align-items-center justify-content-center bg-white bg-opacity-25"
                  style={{
                    width: "52px",
                    height: "52px",
                    borderRadius: "16px",
                  }}
                >
                  <FaUser size={22} />
                </div>

                <div>
                  <h5 className="fw-bold mb-1">
                    ثبت درخواست مشتری
                  </h5>

                  <small className="text-white-50">
                    اطلاعات مشتری و دستگاه را وارد کنید
                  </small>
                </div>

              </div>
            </div>

            {/* Body */}
            <div className="card-body p-3 p-md-4">

              <form onSubmit={this.handleSubmit}>

                {/* اطلاعات مشتری */}
                <div className="mb-4">

                  <div className="d-flex align-items-center mb-3">
                    <span
                      className="bg-primary rounded-pill ms-2"
                      style={{
                        width: "4px",
                        height: "20px",
                      }}
                    />

                    <span className="fw-bold text-dark">
                      اطلاعات مشتری
                    </span>
                  </div>

                  {/* نام */}
                  <div className="input-group mb-3">

                    <span
                      className="input-group-text bg-light border-0"
                      style={{
                        borderRadius: "0 14px 14px 0",
                      }}
                    >
                      <FaUser className="text-primary" />
                    </span>

                    <input
                      type="text"
                      className="form-control border-0 bg-light shadow-none"
                      placeholder="نام کامل"
                      value={fullName}
                      onChange={this.handleChange("fullName")}
                      style={{
                        height: "55px",
                        borderRadius: "14px 0 0 14px",
                      }}
                    />

                  </div>

                  {/* موبایل */}
                  <div className="input-group mb-3">

                    <span
                      className="input-group-text bg-light border-0"
                      style={{
                        borderRadius: "0 14px 14px 0",
                      }}
                    >
                      <FaPhone className="text-primary" />
                    </span>

                    <input
                      type="tel"
                      inputMode="numeric"
                      className="form-control border-0 bg-light shadow-none"
                      placeholder="شماره موبایل"
                      value={mobile}
                      onChange={this.handleChange("mobile")}
                      style={{
                        height: "55px",
                        borderRadius: "14px 0 0 14px",
                      }}
                    />

                  </div>

                  {/* تلفن ثابت */}
                  <div className="input-group mb-3">

                    <span
                      className="input-group-text bg-light border-0"
                      style={{
                        borderRadius: "0 14px 14px 0",
                      }}
                    >
                      <FaPhone className="text-primary" />
                    </span>

                    <input
                      type="tel"
                      inputMode="numeric"
                      className="form-control border-0 bg-light shadow-none"
                      placeholder="تلفن ثابت"
                      value={landline}
                      onChange={this.handleChange("landline")}
                      style={{
                        height: "55px",
                        borderRadius: "14px 0 0 14px",
                      }}
                    />

                  </div>

                  {/* استان */}
                  <div className="input-group mb-3">

                    <span
                      className="input-group-text bg-light border-0"
                      style={{
                        borderRadius: "0 14px 14px 0",
                      }}
                    >
                      <FaMapMarkerAlt className="text-primary" />
                    </span>

                    <select
                      className="form-select border-0 bg-light shadow-none"
                      value={province}
                      onChange={this.handleChange("province")}
                      style={{
                        height: "55px",
                        borderRadius: "14px 0 0 14px",
                      }}
                    >
                      <option value="" disabled>
                        استان
                      </option>

                      <option value="tehran">
                        تهران
                      </option>

                      <option value="isfahan">
                        اصفهان
                      </option>

                      <option value="fars">
                        فارس
                      </option>

                      <option value="khorasan-razavi">
                        خراسان رضوی
                      </option>

                      <option value="alborz">
                        البرز
                      </option>
                    </select>

                  </div>

                  {/* آدرس */}
                  <div className="input-group">

                    <span
                      className="input-group-text bg-light border-0"
                      style={{
                        borderRadius: "0 14px 14px 0",
                      }}
                    >
                      <FaMapMarkerAlt className="text-primary" />
                    </span>

                    <input
                      type="text"
                      className="form-control border-0 bg-light shadow-none"
                      placeholder="آدرس"
                      value={address}
                      onChange={this.handleChange("address")}
                      style={{
                        height: "55px",
                        borderRadius: "14px 0 0 14px",
                      }}
                    />

                  </div>

                </div>

                {/* اطلاعات دستگاه */}
                <div className="mb-4">

                  <div className="d-flex align-items-center mb-3">
                    <span
                      className="bg-primary rounded-pill ms-2"
                      style={{
                        width: "4px",
                        height: "20px",
                      }}
                    />

                    <span className="fw-bold text-dark">
                      اطلاعات دستگاه
                    </span>
                  </div>

                  {/* نوع دستگاه */}
                  <div className="input-group mb-3">

                    <span
                      className="input-group-text bg-light border-0"
                      style={{
                        borderRadius: "0 14px 14px 0",
                      }}
                    >
                      <FaImage className="text-primary" />
                    </span>

                    <select
                      className="form-select border-0 bg-light shadow-none"
                      value={deviceType}
                      onChange={this.handleChange("deviceType")}
                      style={{
                        height: "55px",
                        borderRadius: "14px 0 0 14px",
                      }}
                    >
                      <option value="" disabled>
                        نوع دستگاه
                      </option>

                      <option value="washer">
                        ماشین لباسشویی
                      </option>

                      <option value="fridge">
                        یخچال
                      </option>

                      <option value="ac">
                        کولر گازی
                      </option>

                      <option value="tv">
                        تلویزیون
                      </option>
                    </select>

                  </div>

                  {/* برند */}
                  <div className="input-group mb-3">

                    <span
                      className="input-group-text bg-light border-0"
                      style={{
                        borderRadius: "0 14px 14px 0",
                      }}
                    >
                      <FaTag className="text-primary" />
                    </span>

                    <select
                      className="form-select border-0 bg-light shadow-none"
                      value={deviceBrand}
                      onChange={this.handleChange("deviceBrand")}
                      style={{
                        height: "55px",
                        borderRadius: "14px 0 0 14px",
                      }}
                    >
                      <option value="" disabled>
                        برند دستگاه
                      </option>

                      <option value="samsung">
                        سامسونگ
                      </option>

                      <option value="lg">
                        ال‌جی
                      </option>

                      <option value="snowa">
                        اسنوا
                      </option>

                      <option value="pakshoma">
                        پاکشوما
                      </option>
                    </select>

                  </div>

                  {/* ایراد دستگاه */}
                  <div className="input-group mb-3">

                    <span
                      className="input-group-text bg-light border-0"
                      style={{
                        borderRadius: "0 14px 14px 0",
                      }}
                    >
                      <FaQuestionCircle className="text-primary" />
                    </span>

                    <input
                      type="text"
                      className="form-control border-0 bg-light shadow-none"
                      placeholder="ایراد دستگاه"
                      value={deviceIssue}
                      onChange={this.handleChange("deviceIssue")}
                      style={{
                        height: "55px",
                        borderRadius: "14px 0 0 14px",
                      }}
                    />

                  </div>

                  {/* زمان مراجعه */}
                  <div className="input-group mb-3">

                    <span
                      className="input-group-text bg-light border-0"
                      style={{
                        borderRadius: "0 14px 14px 0",
                      }}
                    >
                      <FaClock className="text-primary" />
                    </span>

                    <input
                      type="text"
                      className="form-control border-0 bg-light shadow-none"
                      placeholder="زمان مراجعه"
                      value={visitTime}
                      onChange={this.handleChange("visitTime")}
                      style={{
                        height: "55px",
                        borderRadius: "14px 0 0 14px",
                      }}
                    />

                  </div>

                  {/* توضیحات */}
                  <div className="input-group">

                    <span
                      className="input-group-text bg-light border-0"
                      style={{
                        borderRadius: "0 14px 14px 0",
                      }}
                    >
                      <FaLink className="text-primary" />
                    </span>

                    <input
                      type="text"
                      className="form-control border-0 bg-light shadow-none"
                      placeholder="توضیحات"
                      value={description}
                      onChange={this.handleChange("description")}
                      style={{
                        height: "55px",
                        borderRadius: "14px 0 0 14px",
                      }}
                    />

                  </div>

                </div>

                {/* دکمه ثبت */}
                <button
                  type="submit"
                  className="btn btn-primary w-100 border-0 fw-bold shadow-sm"
                  style={{
                    height: "56px",
                    borderRadius: "15px",
                    background:
                      "linear-gradient(135deg, #0d6efd, #4f46e5)",
                  }}
                >
                  ثبت درخواست
                </button>

              </form>

            </div>
          </div>

          <div className="text-center mt-3">
            <small className="text-muted">
              لطفاً اطلاعات را با دقت وارد کنید
            </small>
          </div>

        </div>
      </div>
    );
  }
}

export default CustomerRequestForm;
